  const primeBand = (y > 29 && y < 31) || (y > 59 && y < 61) || (y > 89 && y < 91) ? 0.25 : 0;
  const tokenDots = Math.sin(x*p(8)*0.1)*Math.sin(y*p(9)*0.1) > 0.85 ? 0.2 : 0;
